// Ficha Oculta RPG 0.23-teste — versão de TESTE com um arquivo de código só (montada a partir dos módulos de js/).
'use strict';
let __dadosP;
const __carregarDados = () => (__dadosP ||= fetch('dados/dados.json?v=0.23-teste', { cache: 'no-cache' })
  .then(r => { if (!r.ok) throw new Error('dados.json indisponível'); return r.json(); })
  .catch(e => { __dadosP = undefined; throw e; }));
const __buscarDados = async sel => {
  try { const d = await __carregarDados(); const v = sel(d); return { ok: v != null, json: async () => v }; }
  catch (e) { return { ok: false, json: async () => null }; }
};
const __SIGILOS = {"sigilo-medo": "data:image/svg+xml;base64,", "sigilo-conhecimento": "data:image/svg+xml;base64,", "sigilo-sangue": "data:image/svg+xml;base64,", "sigilo-energia": "data:image/svg+xml;base64,", "sigilo-variavel": "data:image/svg+xml;base64,", "sigilo-morte": "data:image/svg+xml;base64,"};

// ===== dados.js =====
const __m_dados = (() => {
// dados.js — rola dados. Base: dados.js do Tabuleiro do Arcana (sorteio justo com crypto)
// + o TESTE do Ordem Paranormal: rola N d20 e fica com o MELHOR (ou o PIOR, se o atributo for 0).

function d(lados) {
  // sorteio sem viés: descarta valores que deixariam alguns lados mais prováveis
  const limite = Math.floor(0x100000000 / lados) * lados;
  const n = new Uint32Array(1);
  do crypto.getRandomValues(n); while (n[0] >= limite);
  return (n[0] % lados) + 1;
}

// "2d6+3" -> [{ sinal: 1, n: 2, lados: 6 }, { sinal: 1, valor: 3 }]
function analisar(texto) {
  const limpo = String(texto || '').toLowerCase().replace(/\s+/g, '').replace(/−/g, '-');
  if (!limpo || limpo.length > 80 || !/^[-+]?(\d*d\d+|\d+)([-+](\d*d\d+|\d+))*$/.test(limpo)) throw new Error(`Não entendi "${texto}". Use algo como 2d6+3.`);
  const termos = [];
  for (const m of limpo.matchAll(/([-+]?)(\d*)d(\d+)|([-+]?)(\d+)/g)) {
    if (m[3]) {
      const n = Number(m[2] || 1), lados = Number(m[3]);
      if (n < 1 || n > 100 || lados < 1 || lados > 1000) throw new Error('Use de 1 a 100 dados, com até 1000 lados.');
      termos.push({ sinal: m[1] === '-' ? -1 : 1, n, lados });
    } else termos.push({ sinal: m[4] === '-' ? -1 : 1, valor: Number(m[5]) });
  }
  return termos;
}

// Rola uma expressão de dano/efeito. Crítico no Ordem: MULTIPLICA os dados da arma (x2, x3…); bônus fixos não.
// Multiplica os grupos da arma marcados no cálculo, inclusive Lancinante. Devolve { expr, total, detalhe, dados }.
function rolar(expr, { multiplicador = 1, gruposCritico = 1 } = {}) {
  const termos = analisar(expr);
  let total = 0, grupo = 0;
  const pedacos = [], dados = [];
  for (const t of termos) {
    if (t.valor != null) { total += t.sinal * t.valor; pedacos.push((t.sinal < 0 ? '− ' : '+ ') + t.valor); continue; }
    const n = grupo++ < gruposCritico ? t.n * multiplicador : t.n;
    const valores = Array.from({ length: Math.min(200, n) }, () => d(t.lados));
    const soma = valores.reduce((a, b) => a + b, 0);
    total += t.sinal * soma;
    dados.push({ lados: t.lados, valores });
    pedacos.push((t.sinal < 0 ? '− ' : '+ ') + `[${valores.join(', ')}]`);
  }
  const detalhe = pedacos.join(' ').replace(/^\+ /, '');
  return { expr: String(expr).replace(/\s+/g, ''), total, detalhe, dados };
}

// TESTE do Ordem: qtd d20, fica com o melhor (ou pior). bonus = soma fixa. margem = crítico (ataques).
function rolarTeste({ qtd = 1, pior = false, bonus = 0, margem = 21 } = {}) {
  qtd = Math.max(1, Math.min(20, qtd));
  const valores = Array.from({ length: qtd }, () => d(20));
  const escolhido = pior ? Math.min(...valores) : Math.max(...valores);
  const indice = valores.indexOf(escolhido);
  return { valores, escolhido, indice, pior, bonus, total: escolhido + bonus, critico: escolhido >= margem, natural20: escolhido === 20, natural1: escolhido === 1 };
}

const comSinal = n => (n >= 0 ? '+' : '−') + Math.abs(n);
// "3d20+5" no jeito do livro: 3O+5 (O = dado). Aqui escrevemos "3d20 +5" e "pior de 2d20" quando atributo 0.
const textoTeste = ({ qtd, pior }, bonus) => `${pior ? 'pior de ' : ''}${qtd}d20${bonus ? ' ' + comSinal(bonus) : ''}`;

return { d, analisar, rolar, rolarTeste, comSinal, textoTeste };
})();

// ===== dano.js =====
const __m_dano = (() => {
const { d: dado, rolarTeste } = __m_dados;

function sofrerDano(ficha, d, quantidade, { tipo = 'pv', rd = 0, metade = 0, ignorarTemp = false } = {}) {
  const recurso = tipo === 'mental' ? d.pd ? 'pd' : 'san' : 'pv';
  const total = Math.max(0, Math.floor(quantidade / (2 ** metade)) - Math.max(0, rd));
  const absorvido = recurso === 'pv' && !ignorarTemp ? Math.min(ficha.recursos.pvTemp, total) : 0;
  ficha.recursos.pvTemp -= absorvido;
  ficha.recursos[recurso] = d.atual[recurso] - (total - absorvido);
  return { total, absorvido, recurso, atual: ficha.recursos[recurso] };
}

function recuperar(ficha, d, recurso, quantidade) {
  const maximo = { pv: d.pv, pe: d.pe, pd: d.pdMax, san: d.san }[recurso];
  const novo = Math.min(maximo, d.atual[recurso] + quantidade);
  ficha.recursos[recurso] = novo;
  return novo;
}

const EVOLUCAO_CONDICAO = { fraco: 'debilitado', debilitado: 'inconsciente', fatigado: 'exausto', exausto: 'inconsciente', frustrado: 'esmorecido' };
const DERIVADAS = {
  petrificado: ['inconsciente'], inconsciente: ['indefeso'], paralisado: ['imovel', 'indefeso'],
  indefeso: ['desprevenido'], cego: ['desprevenido', 'lento'], atordoado: ['desprevenido'], surpreendido: ['desprevenido'],
  agarrado: ['imovel', 'desprevenido'], enredado: ['lento', 'vulneravel'], exausto: ['debilitado', 'lento', 'vulneravel'],
  fatigado: ['fraco', 'vulneravel'],
};

function condicoesEfetivas(condicoes) {
  const resultado = new Set();
  function incluir(id) {
    if (resultado.has(id)) return;
    resultado.add(id);
    for (const derivada of DERIVADAS[id] || []) incluir(derivada);
  }
  condicoes.forEach(incluir);
  return resultado;
}

function adicionarCondicao(ficha, id) {
  const anterior = ficha.condicoes.includes(id);
  if (!anterior) return ficha.condicoes.push(id);
  const seguinte = EVOLUCAO_CONDICAO[id];
  if (!seguinte) return;
  ficha.condicoes = ficha.condicoes.filter(x => x !== id);
  adicionarCondicao(ficha, seguinte);
}

function resolverCondicoesDoTurno(ficha, calcular, rolarDado = dado, testar = rolarTeste) {
  const avisos = [];
  let d = calcular(ficha);
  if (d.condicoesEfetivas.has('em-chamas')) {
    const q = rolarDado(6);
    sofrerDano(ficha, d, q, { rd: d.rd });
    avisos.push(`Em Chamas: ${q} de dano de fogo antes de RD.`);
    d = calcular(ficha);
  }
  if (d.condicoesEfetivas.has('sangrando')) {
    const n = ficha.atributos.vig + d.ajusteDados.vig + d.ajusteDados.todos;
    const t = testar({ qtd: n >= 1 ? n : 2 - n, pior: n < 1 });
    if (t.total >= 20) {
      ficha.condicoes = ficha.condicoes.filter(x => x !== 'sangrando');
      avisos.push('Sangramento estabilizado pelo teste de Vigor.');
    } else {
      const q = rolarDado(6);
      sofrerDano(ficha, d, q, { ignorarTemp: true });
      avisos.push(`Sangramento: perda de ${q} PV.`);
    }
  }
  return avisos;
}

return { sofrerDano, recuperar, condicoesEfetivas, adicionarCondicao, resolverCondicoesDoTurno };
})();

// ===== aprendizado.js =====
const __m_aprendizado = (() => {
const RITUAIS_DE_TRILHA = {
  'canalizar-o-medo': 'conduite',
  'conhecendo-o-medo': 'graduado',
  'lamina-do-medo': 'lamina',
  'medo-tangivel': 'flagelador',
  'presenca-do-medo': 'intuitivo',
};

const circuloDeAprender = nex => nex >= 75 ? 3 : nex >= 45 ? 2 : 1;

function cabemNosLimites(rituais, vagas) {
  const limites = vagas.slice().sort((a, b) => b - a);
  return rituais.slice().sort((a, b) => b - a).every((c, i) => c <= (limites[i] ?? 0));
}

function problemaAoAprender(ficha, derivada, ritual) {
  const trilha = RITUAIS_DE_TRILHA[ritual.id];
  if (ficha.rituais.some(r => r.nome === ritual.nome)) return 'Ritual já conhecido.';
  if (ritual.fonte === 'SaH' && ficha.modo !== 'sah') return 'Este ritual pertence ao modo Sobrevivendo ao Horror.';
  if (trilha) return ficha.trilha === trilha && derivada.trilhaHabs.some(h => h.nivel === 20 && h.liberada)
    ? '' : 'Este ritual exige a habilidade final da trilha correspondente.';
  if (ritual.ritualExigido && !ficha.rituais.some(r => r.nome === ritual.ritualExigido)) return `Exige conhecer ${ritual.ritualExigido}.`;
  if (ritual.requerAfinidades && !ritual.requerAfinidades.every(el => derivada.afinidade === el)) return 'Falta afinidade com os elementos exigidos.';
  if (derivada.vagasEspecificas.includes(ritual.id)) return '';
  const niveis = ficha.rituais.filter(r => !r.proprio && !derivada.vagasEspecificas.includes(r.idCatalogo)).map(r => r.circulo);
  return cabemNosLimites([...niveis, ritual.circulo], derivada.vagasRituais)
    ? '' : 'Nenhuma vaga permite este círculo neste momento.';
}

function viaPoder(ficha, d, poder) {
  if (poder.id === 'transcender' && d.transcenderSeparado) return d.transcenderes < d.limiteTranscender ? 'nex' : '';
  const possuiVivencia = d.faixa?.id === 'adulto' && ficha.classe !== 'mundano';
  const vivenciaUsada = ficha.poderes.some(p => p.via === 'vivencia');
  const vagasComuns = d.slotsPoder - Number(possuiVivencia) + Number(d.versatilidade && !ficha.escolhas.versatilidade);
  const comuns = ficha.poderes.filter(p => !p.via && p.id !== 'proprio' && !(p.id === 'transcender' && d.transcenderSeparado)).length;
  const total = comuns + Number(vivenciaUsada);
  if (total >= vagasComuns + Number(possuiVivencia)) return '';
  const elegivelVivencia = poder.classe === ficha.classe || poder.classe === 'todas';
  if (possuiVivencia && !vivenciaUsada && elegivelVivencia && poder.id !== 'transcender') return 'vivencia';
  return comuns + Number(!possuiVivencia && vivenciaUsada) < vagasComuns ? 'classe' : '';
}

return { RITUAIS_DE_TRILHA, circuloDeAprender, problemaAoAprender, viaPoder };
})();

